// Import of required libraries
import { test, expect, getBaseUrl, newSkyrampPlaywrightPage } from '@skyramp/skyramp';
import { signIn, dismissProjectOwnerPrompt, openUserRolesSettings, openTableRowDetail } from './skyrampUtils';

const pageTimeout = 15000;

// URL for test requests
const baseUrl = getBaseUrl("SKYRAMP_TEST_BASE_URL", "http://localhost:8055");

test.use({
    viewport: { width: 1280, height: 900 },
});

test('testUi', async ({ page }) => {
    test.setTimeout(115000);

    // set default timeout for all locator/page actions in this test
    page.setDefaultTimeout(pageTimeout);
    // Wrap playwright page with Skyramp page
    page = newSkyrampPlaywrightPage(page);

    await page.goto(`${baseUrl}/admin/logout`);
    await page.goto(`${baseUrl}/admin/login`);

    await signIn(page, "admin@example.com", "admin");

    await dismissProjectOwnerPrompt(page);

    await openUserRolesSettings(page);

    await expect(page.getByRole("row")).toHaveCount(3);
    await expect(page.getByRole("cell", { name: "Administrator", exact: true })).toHaveText("Administrator");
    await expect(page.getByRole("cell", { name: "Public", exact: true })).toHaveText("Public");
    await expect(page.locator('[data-testid="v-table-skeleton"]')).toHaveCount(0);

    await openTableRowDetail(page);

    await expect(page).toHaveURL(/\/admin\/settings\/roles\/[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i);
    await expect(page.getByRole("heading", { name: "Administrator Role" })).toHaveText("Administrator Role");
    await expect(page.getByRole("textbox", { name: "The unique name for this role" })).toHaveValue("Administrator");
});
